package mz.bam.seeky.android;

import android.app.*;import android.content.*;import android.text.*;import android.widget.*;import java.util.concurrent.ExecutorService;import java.util.List;

/** Gemini-only personal connection; network and storage failures are reported separately. */
final class SeekyAiSettings {
 static String provider(Context c){return SeekyAiCore.GEMINI;}
 static volatile boolean loaded;
 /** The chosen model, the one that worked and the key's model list, kept in the phone's settings. */
 static void load(Context c){if(loaded)return;synchronized(SeekyAiSettings.class){if(loaded)return;SeekyAiService.load(serviceStore(c));SharedPreferences p=c.getApplicationContext().getSharedPreferences("seeky_ai",0);String known=p.getString("gemini_models","");SeekyAiModels.restore(p.getString("gemini_model",""),p.getString("gemini_working",""),known.isEmpty()?java.util.Collections.emptyList():java.util.Arrays.asList(known.split(",")));SeekyAiModels.store=(chosen,working,available)->p.edit().putString("gemini_model",chosen).putString("gemini_working",working).putString("gemini_models",String.join(",",available)).apply();loaded=true;}}
 /** "Automático (recomendado)" first, then the key's text models (or the fallbacks before the first test). */
 static List<String> models(Context c){List<String> out=new java.util.ArrayList<>();out.add(AppLanguage.text(c,"Automático (recomendado)"));List<String> known=SeekyAiModels.available.isEmpty()?java.util.Arrays.asList(SeekyAiModels.FALLBACKS):SeekyAiModels.available;if(known.contains(SeekyAiModels.NEWEST)||SeekyAiModels.available.isEmpty())out.add(SeekyAiModels.NEWEST);for(String m:known)if(!out.contains(m))out.add(m);if(!SeekyAiModels.chosen.isEmpty()&&!out.contains(SeekyAiModels.chosen))out.add(SeekyAiModels.chosen);return out;}
 static boolean allowed(Context c,String ignored){load(c);SharedPreferences p=c.getSharedPreferences("seeky_ai",0);return p.getBoolean("configured_gemini",false)&&p.getBoolean("terms_gemini",false)||SeekyAiService.available();}
 /** 5.55: the Seeky IA service (no key needed), kept in the phone's settings; asked again at most every 12 hours. */
 static SeekyAiService.Store serviceStore(Context c){SharedPreferences p=c.getApplicationContext().getSharedPreferences("seeky_ai_service",0);return new SeekyAiService.Store(){public String get(String k,String f){return p.getString(k,f);}public void put(String k,String v){p.edit().putString(k,v).apply();}};}
 static void refreshService(Context c){try{SeekyAiService.refresh(serviceStore(c));}catch(Exception ignored){}}
 static String name(String ignored){return "Google Gemini";}
 interface Verification {void run(String key,SeekyAiClient.Call call)throws Exception;}
 static void show(Activity a,SeekyAiVault vault,ExecutorService worker,Runnable changed){show(a,vault,worker,changed,SeekyAiClient::testConnection);}
 static void show(Activity a,SeekyAiVault vault,ExecutorService worker,Runnable changed,Verification verification){AppPalette colors=AppPalette.of(a);LinearLayout form=new LinearLayout(a);form.setOrientation(1);
  TextView service=new TextView(a);service.setText("Google Gemini");service.setTextColor(colors.ink);service.setTextSize(18);form.addView(service);
  EditText key=new EditText(a);key.setHint(AppLanguage.text(a,"Chave pessoal · deixe vazio para manter a guardada"));key.setInputType(InputType.TYPE_CLASS_TEXT|InputType.TYPE_TEXT_VARIATION_PASSWORD);key.setSingleLine(true);key.setSaveEnabled(false);key.setImportantForAutofill(android.view.View.IMPORTANT_FOR_AUTOFILL_NO_EXCLUDE_DESCENDANTS);key.setFilters(new InputFilter[]{new InputFilter.LengthFilter(2048)});form.addView(key);
  TextView info=new TextView(a);info.setTextColor(colors.muted);info.setTextSize(13);info.setText(AppLanguage.text(a,"Use uma chave do Google AI Studio num projecto sem facturação. O Seeky não verifica a facturação. A quota gratuita pode permitir o uso dos textos para melhorar os serviços Google. O teste gera uma resposta curta e pode consumir quota. Não envia documentos."));form.addView(info);
  load(a);if(SeekyAiService.available()){TextView svc=new TextView(a);svc.setTextColor(colors.accent);svc.setTextSize(13);svc.setPadding(0,PlusUi.dp(a,8),0,0);svc.setText(AppLanguage.text(a,"Sem chave, o Seeky IA já funciona pelo serviço do Seeky.")+" "+AppLanguage.text(a,SeekyAiService.about()));form.addView(svc);}
  TextView modelLabel=new TextView(a);modelLabel.setText(AppLanguage.text(a,"Modelo"));modelLabel.setTextColor(colors.muted);modelLabel.setTextSize(13);modelLabel.setPadding(0,PlusUi.dp(a,10),0,0);form.addView(modelLabel);
  ChoiceSpinner model=new ChoiceSpinner(a);List<String> names=models(a);List<String> shown=new java.util.ArrayList<>();for(int i=0;i<names.size();i++)shown.add(i==0?names.get(0):AppLanguage.text(a,SeekyAiModels.label(names.get(i))));model.setAdapter(new ArrayAdapter<String>(a,android.R.layout.simple_spinner_dropdown_item,shown));model.setSelection(SeekyAiModels.chosen.isEmpty()?0:Math.max(0,names.indexOf(SeekyAiModels.chosen)));model.setContentDescription(AppLanguage.text(a,"Modelo"));form.addView(model,new LinearLayout.LayoutParams(-1,PlusUi.dp(a,48)));
  TextView modelInfo=new TextView(a);modelInfo.setTextColor(colors.muted);modelInfo.setTextSize(12);modelInfo.setText(AppLanguage.text(a,"Automático usa")+" "+SeekyAiModels.current()+(SeekyAiModels.available.isEmpty()?". "+AppLanguage.text(a,"Toque em Testar e guardar para ver os modelos desta chave."):". "+AppLanguage.text(a,"Se a Google retirar um modelo, o Seeky passa sozinho ao seguinte.")));form.addView(modelInfo);
  TextView status=new TextView(a);status.setTextColor(colors.ink);status.setTextSize(14);status.setTextIsSelectable(true);form.addView(status);
  CheckBox terms=new CheckBox(a);terms.setText(AppLanguage.text(a,"Confirmo que usarei quota gratuita ou créditos promocionais, sem facturação/recarregamento automático. Compreendi o envio de texto."));terms.setTextColor(colors.ink);form.addView(terms);
  SeekyAiClient.Call call=new SeekyAiClient.Call();
  UiDialog dialog=new UiDialog.Builder(a).setTitle("Ligação da IA").setView(form).setPositiveButton("Testar e guardar",null).setNeutralButton("Remover chaves",null).setNegativeButton("Cancelar",(d,w)->call.cancel()).create();dialog.show();dialog.setOnCancelListener(d->call.cancel());
  dialog.getButton(-1).setOnClickListener(v->{if(!terms.isChecked()){status.setText(AppLanguage.text(a,"Confirme as condições antes de guardar."));return;}String entered=SeekyAiClient.normaliseKey(key.getText().toString());if(!entered.isEmpty()&&!SeekyAiClient.validKey(entered)){status.setText(AppLanguage.text(a,"Chave inválida. Copie a chave completa, sem espaços."));return;}
   dialog.getButton(-1).setEnabled(false);dialog.getButton(-3).setEnabled(false);key.setEnabled(false);status.setText(AppLanguage.text(a,"A testar uma resposta do Gemini…"));
   worker.execute(()->{String stage="read";try{String secret=entered.isEmpty()?vault.get(SeekyAiCore.GEMINI):entered;if(secret.isEmpty())throw new java.io.IOException("Introduza uma chave do Google AI Studio.");stage="network";int picked=model.getSelectedItemPosition();String wanted=picked<=0?"":names.get(picked);SeekyAiModels.choose(wanted);verification.run(secret,call);call.check();stage="storage";if(!entered.isEmpty())vault.put(SeekyAiCore.GEMINI,secret);if(!a.getSharedPreferences("seeky_ai",0).edit().putString("provider",SeekyAiCore.GEMINI).putBoolean("configured_gemini",true).putBoolean("terms_gemini",true).commit())throw new java.io.IOException();final String used=SeekyAiModels.working.isEmpty()?SeekyAiModels.current():SeekyAiModels.working;final String switched=SeekyAiModels.takeNotice();a.runOnUiThread(()->{if(a.isFinishing()||a.isDestroyed()||call.cancelled.get())return;key.setText("");dialog.dismiss();android.widget.Toast.makeText(a,(switched.isEmpty()?"":switched+"\n")+AppLanguage.text(a,"Ligado ao Gemini · modelo")+" "+used,android.widget.Toast.LENGTH_LONG).show();changed.run();});}
    catch(Exception e){final String message=stage.equals("storage")?"A ligação ao Gemini funciona, mas não foi possível proteger a chave neste aparelho. Remova as chaves e tente guardar novamente.":stage.equals("read")?"Não foi possível ler a chave guardada. Cole uma nova chave para substituir o registo anterior.":e instanceof java.io.IOException&&e.getMessage()!=null?e.getMessage():"Falha de ligação segura ao Gemini. Verifique a Internet e a data/hora do aparelho.";a.runOnUiThread(()->{if(a.isFinishing()||a.isDestroyed()||call.cancelled.get())return;dialog.getButton(-1).setEnabled(true);dialog.getButton(-3).setEnabled(true);key.setEnabled(true);status.setText(AppLanguage.text(a,message));});}
   });
  });
  dialog.getButton(-3).setOnClickListener(v->new UiDialog.Builder(a).setTitle("Remover as chaves deste aparelho?").setMessage("As conversas guardadas são conservadas.").setPositiveButton("Remover",(d,w)->worker.execute(()->{vault.clear();a.getSharedPreferences("seeky_ai",0).edit().clear().commit();SeekyAiModels.restore("","",java.util.Collections.emptyList());a.runOnUiThread(()->{if(!a.isFinishing()&&!a.isDestroyed()){dialog.dismiss();android.widget.Toast.makeText(a,AppLanguage.text(a,"Chaves removidas."),android.widget.Toast.LENGTH_SHORT).show();}});})).setNegativeButton("Cancelar",null).show());
 }
}
